contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount is the amount to send to c in the deposit call.
    // anUnused is just an extra parameter to satisfy input variability requirements.
    function run(uint depositAmount, uint anUnused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // balances before deposit
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit to C
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // balances immediately after deposit
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // balances after withdrawAll
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: either withdrawAll reverted, or C's decrease equals this contract's increase
        // observed relative to the state immediately after deposit.
        // Use non-underflowing comparisons: ensure midC >= afterC and afterThis >= midThis when not reverted.
        assert(reverted || ((midC >= afterC) && (afterThis >= midThis) && ((midC - afterC) == (afterThis - midThis))));
    }

    receive() external payable {}
}

