// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, uint256 anUnused) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint midC = address(c).balance;
        uint midThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(reverted || ((midC >= afterC) && (afterThis >= midThis) && ((midC - afterC) == (afterThis - midThis))));
    }

    function testFuzz_run(uint256 depositAmount, uint256 anUnused) public {
        _run(depositAmount, anUnused);
    }

    receive() external payable {}
}
